+        if (vertices < 0) {
+            throw new IllegalArgumentException("vertices must be non-negative");
+        }
+
+        List<List<Integer>> adjacencyList = new ArrayList<>(vertices);
+        for (int vertex = 0; vertex < vertices; vertex++) {
+            adjacencyList.add(new ArrayList<>());
